function countUp(element,target,duration){const startTime=performance.now(),isDecimal=String(target).includes("."),suffix=element.dataset.suffix||"",prefix=element.dataset.prefix||"";requestAnimationFrame(function tick(now){const elapsed=now-startTime,progress=Math.min(elapsed/duration,1);var t;const current=(t=progress,1-Math.pow(1-t,3))*target;element.textContent=isDecimal?prefix+current.toFixed(1)+suffix:target>=1e3&&"M+"===suffix?prefix+"$"+Math.floor(current)+suffix:prefix+Math.floor(current)+suffix,progress<1?requestAnimationFrame(tick):element.textContent=element.dataset.final||element.textContent})}function initStatsCounter(){const stats=document.querySelectorAll("[data-count]");if(!stats.length)return;const observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){const el=entry.target;countUp(el,parseFloat(el.dataset.count),parseInt(el.dataset.duration,10)||1800),observer.unobserve(el)}})},{threshold:.3});stats.forEach(function(stat){observer.observe(stat)})}